// BrowserOverrides Browser rendering overrides for a specific crawl request.
//
// The browser tier is supported. Seed URLs are SSRF-checked on every path, so
// the browser carries no exemption; `bypass` and `proxy` are the tiers that
// remain unavailable, and setting either returns HTTP 400.
type BrowserOverrides struct {
	// Backend Browser backend. One of `native` or `chromiumoxide`.
	Backend *string `json:"backend,omitempty"`

	// Mode Browser mode. One of `auto`, `always` or `never`.
	Mode *string `json:"mode,omitempty"`

	// Stealth Route every request through the browser's stealth tier (JS stealth
	// patches, TLS fingerprint spoofing, stealth user agent). Works on both
	// backends; cannot combine with `mode: "never"`. An explicit `false`
	// opts out of stealth even when the crawl pod defaults to it; an
	// explicit `mode` keeps precedence either way.
	Stealth *bool `json:"stealth,omitempty"`
}

