// JobResult The result envelope `GET /v1/jobs/{id}/result` serves on both tiers.
//
// `results` holds the extracted document(s) produced by this job, in
// discovery order: a one-element vector for the common single-document case.
// The two tiers model multi-document splits differently, and this DTO carries
// both. Pro inlines every document in `results`. Enterprise runs one document
// per job, spawns child jobs for a split, and lists their IDs in
// `child_job_ids`, each retrievable on this route.
//
// Each tier stores the result in its own layout (Pro: an object per job;
// Enterprise: a NATS KV envelope with a 12 hour TTL, offloaded to object
// storage above a size threshold). Both translate to this envelope at the
// HTTP boundary, and both answer 409 with [`JobResult::not_ready_message`]
// while the job is not in a terminal successful state.
type JobResult struct {
	// ChildJobIds Child job IDs when this job was split into multiple jobs (Enterprise
	// boundary splitting). Each is retrievable via `GET /v1/jobs/{id}`. Empty
	// when the job produced no child jobs (always empty on Pro).
	ChildJobIds *[]string `json:"child_job_ids,omitempty"`

	// CompletedAt ISO 8601 completion timestamp, when available.
	CompletedAt *string `json:"completed_at,omitempty"`

	// Errors Non-fatal per-document errors.
	Errors *[]JobResultError `json:"errors,omitempty"`

	// JobId The job this result belongs to.
	JobId openapi_types.UUID `json:"job_id"`

	// Results Extracted documents, present once the job reaches a terminal
	// successful state (`completed` or `partial_success`).
	//
	// Opaque JSON on purpose: each document is `xberg::types::ExtractedDocument`
	// plus the keys the structured pipeline merges in (`structured_output`,
	// `structured_output_flat`). Passing the stored document through untouched
	// is what keeps those keys on the wire; a typed round trip through the
	// engine's document type dropped every key that type does not declare.
	Results *[]JobResultDocument `json:"results,omitempty"`

	// Status Job status at the time the result was read.
	Status JobStatus `json:"status"`
}

