// TesseractConfig Tesseract OCR configuration.
//
// Provides fine-grained control over Tesseract OCR engine parameters.
// Most users can use the defaults, but these settings allow optimization
// for specific document types (invoices, handwriting, etc.).
//
// **This is the public-facing counterpart of `ocr::types::TesseractConfig`
// (the internal, engine-facing representation with `u8`/`String` fields instead of
// `i32`/`Vec<String>`).** They are two independent struct definitions bridged only by
// an explicit `From<&TesseractConfig> for crate::ocr::types::TesseractConfig` impl in
// `ocr/types.rs` — that conversion carries field *values* across, but each struct keeps
// its own `Default` impl, and the conversion does nothing to keep those two defaults in
// sync. Several production call sites (`extractors::image::apply_default_tesseract_psm`,
// `configured_region_ocr`, `sparse_image_ocr_fallback_config`) construct *this* struct's
// default and convert it, bypassing the internal struct's `Default` entirely — so if the
// two defaults disagree, standalone image OCR silently uses this struct's value while
// PDF-embedded OCR (which can reach the internal `Default` directly when no
// `tesseract_config` is set) uses the other. When changing a default here, also update
// `ocr::types::TesseractConfig::default`, and vice versa.
type TesseractConfig struct {
	// ClassifyUsePreAdaptedTemplates Use pre-adapted templates for character classification
	ClassifyUsePreAdaptedTemplates *bool `json:"classify_use_pre_adapted_templates,omitempty"`

	// EnableTableDetection Enable automatic table detection and reconstruction
	EnableTableDetection *bool `json:"enable_table_detection,omitempty"`

	// Language Language code(s) for OCR recognition. For Tesseract, languages are joined with "+".
	//
	// A list is the canonical form and the only form accepted by the binding
	// object APIs (Python, Node, PHP, WASM, etc.): `["eng", "deu"]`. When
	// deserializing from a config file, JSON body, or the REST/MCP API, a
	// single string is also accepted, either as one code ("eng") or
	// "+"-joined ("eng+deu").
	Language *[]string `json:"language,omitempty"`

	// LanguageModelNgramOn Enable N-gram language model.
	//
	// Kept on by default (see [`Self::default`] and
	// `ocr::types::TesseractConfig::language_model_ngram_on` for the rationale);
	// keep this field's default in sync with the internal struct's.
	LanguageModelNgramOn *bool `json:"language_model_ngram_on,omitempty"`

	// MinConfidence Minimum confidence threshold (0.0-100.0).
	//
	// Words with confidence below this threshold may be rejected or flagged.
	MinConfidence *float64 `json:"min_confidence,omitempty"`

	// Oem OCR Engine Mode (0-3).
	//
	// - 0: Legacy engine only
	// - 1: Neural nets (LSTM) only (usually best)
	// - 2: Legacy + LSTM
	// - 3: Default (based on what's available)
	Oem *int32 `json:"oem,omitempty"`

	// OutputFormat Output format ("text" or "markdown")
	OutputFormat  *string                   `json:"output_format,omitempty"`
	Preprocessing *ImagePreprocessingConfig `json:"preprocessing,omitempty"`

	// Psm Page Segmentation Mode (0-13).
	//
	// Common values:
	// - 3: Fully automatic page segmentation (native default)
	// - 6: Assume a single uniform block of text (WASM default — avoids layout-analysis hang)
	// - 11: Sparse text with no particular order
	Psm *int32 `json:"psm,omitempty"`

	// TableColumnThreshold Column threshold for table detection (pixels)
	TableColumnThreshold *int32 `json:"table_column_threshold,omitempty"`

	// TableMinConfidence Minimum confidence threshold for table detection (0.0-1.0)
	TableMinConfidence *float64 `json:"table_min_confidence,omitempty"`

	// TableRowThresholdRatio Row threshold ratio for table detection (0.0-1.0)
	TableRowThresholdRatio *float64 `json:"table_row_threshold_ratio,omitempty"`

	// TesseditCharBlacklist Blacklist of forbidden characters (empty = none forbidden)
	TesseditCharBlacklist *string `json:"tessedit_char_blacklist,omitempty"`

	// TesseditCharWhitelist Whitelist of allowed characters (empty = all allowed)
	TesseditCharWhitelist *string `json:"tessedit_char_whitelist,omitempty"`

	// TesseditDontBlkrejGoodWds Don't reject good words during block-level processing
	TesseditDontBlkrejGoodWds *bool `json:"tessedit_dont_blkrej_good_wds,omitempty"`

	// TesseditDontRowrejGoodWds Don't reject good words during row-level processing
	TesseditDontRowrejGoodWds *bool `json:"tessedit_dont_rowrej_good_wds,omitempty"`

	// TesseditEnableDictCorrection Enable dictionary correction
	TesseditEnableDictCorrection *bool `json:"tessedit_enable_dict_correction,omitempty"`

	// TesseditUsePrimaryParamsModel Use primary language params model
	TesseditUsePrimaryParamsModel *bool `json:"tessedit_use_primary_params_model,omitempty"`

	// TextordSpaceSizeIsVariable Variable-width space detection
	TextordSpaceSizeIsVariable *bool `json:"textord_space_size_is_variable,omitempty"`

	// ThresholdingMethod Use adaptive thresholding method
	ThresholdingMethod *bool `json:"thresholding_method,omitempty"`

	// UseCache Enable OCR result caching
	UseCache *bool `json:"use_cache,omitempty"`
}

