func (t FormatMetadata) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "archive":
		return t.AsArchiveMetadata()
	case "audio":
		return t.AsAudioMetadata()
	case "bibtex":
		return t.AsBibtexMetadata()
	case "citation":
		return t.AsCitationMetadata()
	case "code":
		return t.AsCodeMetadata()
	case "csv":
		return t.AsCsvMetadata()
	case "dbf":
		return t.AsDbfMetadata()
	case "docx":
		return t.AsDocxMetadata()
	case "email":
		return t.AsEmailMetadata()
	case "epub":
		return t.AsEpubMetadata()
	case "excel":
		return t.AsExcelMetadata()
	case "fiction_book":
		return t.AsFictionBookMetadata()
	case "html":
		return t.AsHtmlMetadata()
	case "image":
		return t.AsImageMetadata()
	case "jats":
		return t.AsJatsMetadata()
	case "ocr":
		return t.AsOcrMetadata()
	case "pdf":
		return t.AsPdfMetadata()
	case "pptx":
		return t.AsPptxMetadata()
	case "pst":
		return t.AsPstMetadata()
	case "text":
		return t.AsTextMetadata()
	case "xml":
		return t.AsXmlMetadata()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

